# -*- coding: utf-8 -*-
"""Extended travel data."""
EXTENDED = {
"foguang": {"meta_desc":"Visit Foguang Temple East Hall, the largest surviving Tang wooden building (857 AD), in Xinzhou, Shanxi.","transport":"Fly into **Taiyuan Wusu Airport** (TYN). Hire private car+driver (~600-800 CNY/day). Drive 4h on mountain roads. No public transit.","stay":"Doucun farmhouse guesthouses (~80-150 CNY). Most day-trip from Taiyuan. Pullman Taiyuan (~500 CNY).","food":"Shanxi: dao xiao mian (knife-cut noodles), guo you rou (pork strips). Noodle shops in Doucun.","season":"Apr-May, Sep-Oct ideal. Avoid Jul-Aug (rain). Winter: icy roads.","tips":"No English signage. Download offline maps. Combine Nanchan (30min apart). Bring cash."},
"nanchan": {"meta_desc":"Visit Nanchan Temple, oldest wooden building in China (782 AD) in Xinzhou, Shanxi.","transport":"Fly TYN. Private car+driver (~600-800 CNY/day). 4h from Taiyuan, 10min hike from parking.","stay":"Day-trip from Taiyuan. Wanda Vista (~600 CNY), Hanting Hotel (~160 CNY).","food":"Dao xiao mian, liang pi, you mian kao lao. One noodle shop at village.","season":"Apr-May, Sep-Oct best. Spring wildflowers.","tips":"Oldest wooden building in China. Modest 3-bay hall. No English, no cards. Bring cash."},
"dayanta": {"meta_desc":"Visit Big Wild Goose Pagoda in Xi\'an. Built 652 AD, Ming rebuild on Tang foundation.","transport":"Fly XIY. Metro Line 3 to Dayanta Station exit B. Buses 5,21,22,23,24,30,41,224,500.","stay":"Wyndham Grand Xi\'an South (~500 CNY, 5min walk). Eastern House Boutique (~350 CNY). Xiangzimen Youth Hostel (~60 CNY/dorm).","food":"Rou jia mo, yang rou pao mo, liang pi. Muslim Quarter 20min taxi.","season":"Apr-May, Sep-Oct. Visit 8AM to avoid crowds. Night fountain show 8:30PM.","tips":"Ming rebuild, NOT Tang original. Combo ticket. Climb 7 floors. Book Shaanxi Museum 3 days ahead."},
"mogao": {"meta_desc":"Visit Mogao Caves, Dunhuang - 200+ Tang cave temples, UNESCO heritage.","transport":"Fly DNH. Shuttle bus from Dunhuang Hotel (20 CNY). Taxi ~60 CNY each way.","stay":"Silk Road Dunhuang Hotel (~400 CNY). Yunfei Youth Hostel (~50 CNY/dorm). Mountain Villa (~600 CNY).","food":"Niu rou mian, shao kao (mutton skewers), yang rou tang. Shazhou Night Market best.","season":"Apr-May, Sep-Oct best. Book 2-3 weeks ahead via WeChat. First morning slot best.","tips":"Guided tours only. No photos inside. Standard Visit 8 caves, 238 CNY. English guides limited."},
"famen": {"meta_desc":"Visit Famen Temple Museum near Xi\'an - greatest Tang archaeological find.","transport":"From Xi\'an: HSR to Baoji (1h, 60 CNY) then taxi 30min. Direct bus 2.5h.","stay":"Day-trip from Xi\'an. Baoji Crowne Plaza (~400 CNY). Famen Temple Hotel (~200 CNY).","food":"Saozi mian, rou jia mo, gan mian pi. Vegetarian restaurant at temple.","season":"Apr-May, Sep-Oct. Museum is climate-controlled. Winter less crowded.","tips":"Above-ground temple is modern. Focus on underground museum and Treasure Gallery. English labels minimal."},
"daming": {"meta_desc":"Visit Daming Palace National Heritage Park, Xi\'an - largest imperial palace ever built.","transport":"Metro Line 2 to Longshouyuan exit D. Line 4 to Daming Palace West. Buses 2,17,22,46,104,309.","stay":"Hilton Xi\'an (~600 CNY, 10min walk). Bell Tower Hotel (~300 CNY). Jinjiang Inn (~150 CNY).","food":"Defachang Dumpling House near Bell Tower. Local noodle shops on Taihua Road.","season":"Apr-May, Sep-Oct comfortable for walking. Summer hot, winter cold.","tips":"Almost nothing above ground. Scale is the point: larger than Forbidden City. Audio guide 40 CNY (English)."},
"datangbuye": {"meta_desc":"Great Tang All Day Mall, Xi\'an - Tang-themed night street. 2010 theme park.","transport":"Metro Line 3 to Dayanta exit C. Line 4 to Datang Furongyuan. Buses 5,21,22,23,24,30,224,500.","stay":"Wyndham Grand Xi\'an South (~500 CNY). Hilton High-tech Zone (~450 CNY).","food":"Tang-themed snack stalls (tourist prices). Yanta West Road for authentic food. Shizi Bing (persimmon cakes).","season":"After dark - go after 7PM. Spring/autumn evenings best.","tips":"2010 theme park, nothing old. Popular for photos, Hanfu costume rentals. Light show 7:30PM. Combine with Big Wild Goose Pagoda 500m north."},
"baoguo": {"meta_desc":"Visit Baoguo Temple Main Hall (1013 AD), oldest wooden building in southern China, Ningbo.","transport":"Fly NGB or HSR from Shanghai (2h)/Hangzhou (1h). Bus 238 from Ningbo (40min). Taxi 30min.","stay":"Crowne Plaza Ningbo (~500 CNY). Home Inn (~180 CNY). Ningbo Marriott (~600 CNY).","food":"Ningbo tang yuan, yellow croaker, crab rice cake. Old Bund area best.","season":"Mar-May, Oct-Nov. Spring cherry blossoms.","tips":"Only Main Hall is Song. Virtually unknown to foreign tourists. Combine Tianyi Pavilion and Ningbo Museum."},
"huqiu": {"meta_desc":"Visit Tiger Hill Pagoda, Suzhou (961 AD) - leaning pagoda predating Pisa by 200 years.","transport":"HSR Shanghai-Suzhou (25min). Bus You 1/You 2 (30min). Metro Line 1 to Yangyu Xiang.","stay":"Pan Pacific Suzhou (~600 CNY). Hantang Inn (~250 CNY). Mingtown Youth Hostel (~60 CNY/dorm).","food":"Song shu gui yu (squirrel fish), xie fen xiaolong. Shantang Street food scene. Song He Lou restaurant.","season":"Mar-May (gardens bloom), Oct-Nov. Avoid Golden Week Oct 1-7.","tips":"Cannot enter pagoda. 3-degree lean visible. Walk the hill, tea houses, Sword Pool. Combine Suzhou Museum and Humble Administrator Garden."},
"kaifengtieta": {"meta_desc":"Visit Kaifeng Iron Pagoda (1049 AD) - only above-ground Song structure in Kaifeng.","transport":"Fly CGO. HSR Zhengzhou-Kaifeng 20min. Buses 1,3,4,20 to Iron Pagoda Park.","stay":"Kaifeng Guesthouse (~350 CNY). Pullman Kaifeng (~450 CNY). 7 Days Inn (~130 CNY).","food":"Guan Tang Bao (soup buns), tong zi ji, hua sheng gao. Drum Tower Night Market 6PM-midnight.","season":"Apr-May, Sep-Oct. Summer hot/humid.","tips":"Only Song structure above ground in Kaifeng. Rest buried 8m under silt. Climb 13 floors. Visit Kaifeng Museum first."},
"jinci": {"meta_desc":"Visit Jinci Temple, Taiyuan - earliest surviving major Song timber hall (1032 AD).","transport":"Fly TYN. Bus 308/804 from Taiyuan station (1h). Taxi 40min.","stay":"Pullman Taiyuan (~500 CNY). Wanda Realm (~400 CNY). Jinjiang Inn (~150 CNY).","food":"Guo you rou, dao xiao mian, lao chen cu (aged vinegar). Taiyuan Noodle House. Liuxiang Food Street.","season":"Apr-May, Sep-Oct. Spring blossoms, ancient cypress trees.","tips":"Hall of Holy Mother has unique carved wooden dragons. Focus on Song hall. 3000-year-old cypress alive. Combine Shanxi Museum."},
"longxing": {"meta_desc":"Visit Longxing Temple, Zhengding - four original Song buildings, tallest Song bronze Guanyin (21.3m).","transport":"HSR Beijing-Shijiazhuang (1h) then taxi 30min. Bus 177 from Shijiazhuang station.","stay":"Intercontinental Shijiazhuang (~500 CNY). Hilton (~450 CNY). Home Inn (~160 CNY).","food":"Ma jia shao ji (stewed chicken), lv rou huo shao. Yanfenglou restaurant.","season":"Apr-May, Sep-Oct. Off foreign tourist circuit.","tips":"Most underrated Song site. 42-arm bronze Guanyin cast 971. Emperor Taizu commissioned. Combine Zhengding wall and Linji Temple."},
"qingmingheyuan": {"meta_desc":"Qingming Riverside Landscape Garden, Kaifeng - 1998 Song dynasty theme park.","transport":"Fly CGO. HSR Zhengzhou-Kaifeng 20min. Buses 1,15,20.","stay":"Kaifeng Guesthouse inside park (~350 CNY). Pullman Kaifeng (~450 CNY). Home Inn (~120 CNY).","food":"Dongjing Restaurant (Song recipes). Drum Tower Night Market. Kaifeng Diyilou baozi since 1922.","season":"Apr-May, Sep-Oct. 9AM opening for all shows.","tips":"1998 theme park - zero historical fabric! Family-friendly. Water Battle 11AM, wedding 2PM, evening show. Budget 4-5h. For real Song: Baoguo Temple."},
}
